import{_ as l,h as r,i as e,c as n,v as t,p as i,x as p,m as s,e as m,S as T}from"./chunks/framework.Dvtg8yj2.js";const E=JSON.parse('{"title":"Temperature / Top-k / Top-p","description":"","frontmatter":{"title":"Temperature / Top-k / Top-p","date":"2026-09-03T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/sampling-temperature-topp.md","filePath":"llm/sampling-temperature-topp.md","lastUpdated":1788454257000}'),k={name:"llm/sampling-temperature-topp.md"};function d(h,a,u,c,_,f){const o=r("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="temperature-top-k-top-p" tabindex="-1">Temperature / Top-k / Top-p <a class="header-anchor" href="#temperature-top-k-top-p" aria-label="Permalink to &quot;Temperature / Top-k / Top-p&quot;">​</a></h1><div class="epigraph"><p>从截断后的核里采样，才能避开既不可信又无益的长尾 token，同时保留头部真正的多峰；温度则决定核里的锋利程度。</p><footer>—— Holtzman et al., The Curious Case of Neural Text Degeneration, ICLR 2020（nucleus / top-$p$）；top-$k$ 见 Fan 等故事生成中的截断采样</footer></div><p>自回归每步有一份词表上的 softmax。温度、top-\\(k\\)、top-\\(p\\) 都不改权重，只改 <em>这一步</em> 用来抽样的分布。温度 \\(T\\) 把 logits 除以 \\(T\\) 再归一化，控制锋利。top-\\(k\\) 只保留分数最高的 \\(k\\) 个 token。top-\\(p\\)（nucleus）取最小的集合，使其概率质量和达到 \\(p\\)，再在该集合上归一化后随机抽。Holtzman 等人指出，纯贪心或束搜索会退化，无截断的采样又会抽到荒谬长尾；核采样是针对开放生成的折中。本篇写三个旋钮各自改了支撑集或温度、它们叠用时谁先谁后、以及何时不该用高随机。与束搜索的目标函数对照见 <a href="/llm/beam-vs-sample">Beam vs Sampling</a>；注意力里的温度是另一条轴，见 <a href="/llm/sdpa">SDPA</a>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>原始 \\(p_\\theta(x_t\\mid x_{&lt;t})\\) 在开放生成里有两个坏区。头部过尖：贪心反复走最高频续写，重复循环。尾部过肥：低概率 token 虽单个很小，词表极大，偶发抽中就会语法崩盘或话题跳脱。产品需要在「永远同一句」和「胡话」之间调一条可用的随机性。三个超参经常被同时打开，却不清楚各自删的是哪一部分质量。再叠 <a href="/llm/constrained-decoding">约束解码</a> 时，合法集合已经很小，再做激进截断会把唯一合法续写剪掉。</p><p>默认值还造成评测与线上分裂。研究脚本 \\(T=0\\)，聊天产品 \\(T=0.8\\) 加 top-\\(p=0.9\\)，数字对不上。需要把三个量写成采样协议的一部分，而不是「生成」二字带过。</p><h3 id="温度改的是分布锋利程度" tabindex="-1">温度改的是分布锋利程度 <a class="header-anchor" href="#温度改的是分布锋利程度" aria-label="Permalink to &quot;温度改的是分布锋利程度&quot;">​</a></h3><p>设 \\(z\\) 为 logits，\\(T&gt;0\\)，则 \\(p_i \\propto \\exp(z_i/T)\\)。\\(T\\to 0\\) 趋向贪心（并列最大时实现相关）。\\(T=1\\) 是模型原分布，策略梯度与对数似然评测通常假设这个。\\(T&gt;1\\) 拉平，长尾变肥；\\(T&lt;1\\) 变尖，接近贪心但未截断支撑。温度 <em>不删除</em> token，只改变相对质量。因此高温仍可能抽到极低 logit 的词，这是 Holtzman 要用核来切尾的原因。低温不能替代 top-\\(p\\)：尖峰仍在全词表上有非零质量，理论上仍能抽到怪词，只是很少。</p><p><span class="marginnote">\\(T=0\\) 在实现里常被写成「取 argmax」，与极小 \\(T\\) 的采样在并列时不同。服务端应把 \\(T=0\\) 当确定性路径，不要再叠随机 top-\\(p\\)（有的实现会忽略 \\(p\\)，有的会在并列核里乱抽）。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>推荐的组合要声明顺序。常见实现：先把 logits 除以 \\(T\\)，softmax 得到 \\(p\\)，再按 top-\\(k\\) 截断（不足 \\(k\\) 个则全留），再按 top-\\(p\\) 在剩余里取核，最后重新归一化采样。也有先 \\(p\\) 后 \\(k\\) 的，结果不同：\\(k\\) 先会限制核的最大尺寸。文档必须写清。\\(k=\\lvert\\mathcal{V}\\rvert\\) 或关闭、\\(p=1\\) 表示该截断关闭。两者同时关且 \\(T=1\\)，才是原模型分布。</p><p>任务上的粗默认：事实问答、代码、结构化 JSON 用低 \\(T\\)（0–0.3）并关闭或放宽截断，让约束文法自己收支撑集。开放闲聊、创意续写用 \\(T\\in[0.7,1.0]\\) 加 \\(p\\in[0.9,0.95]\\)。需要多样性做 <a href="/llm/best-of-n">Best-of-N</a> 或 RL rollout 时，应接近训练时的采样，不要用贪心轨迹去估 \\(\\mathbb{E}_\\pi\\)。top-\\(k\\) 单独用（如 \\(k=50\\)）在早期故事生成里常见，核采样通常对开放文本更稳，因为每步「合理集合」大小随上下文变，\\(k\\) 是僵硬常数。</p>',12)),(e(),i(T,null,{default:p(()=>[m(o,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20Z%5B%22logits%20z%22%5D%20--%3E%20T%5B%22%E9%99%A4%E4%BB%A5%E6%B8%A9%E5%BA%A6%20T%22%5D%0A%20%20T%20--%3E%20K%5B%22%E5%8F%AF%E9%80%89%EF%BC%9A%E4%BF%9D%E7%95%99%20top-k%22%5D%0A%20%20K%20--%3E%20P%5B%22%E5%8F%AF%E9%80%89%EF%BC%9Anucleus%20top-p%22%5D%0A%20%20P%20--%3E%20N%5B%22%E9%87%8D%E6%96%B0%E5%BD%92%E4%B8%80%E5%8C%96%22%5D%0A%20%20N%20--%3E%20S%5B%22%E9%87%87%E6%A0%B7%20token%22%5D%0A"})]),fallback:p(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h3 id="top-k-与核采样" tabindex="-1">Top-k 与核采样 <a class="header-anchor" href="#top-k-与核采样" aria-label="Permalink to &quot;Top-k 与核采样&quot;">​</a></h3><p>top-\\(k\\)：支撑集大小恒为 \\(k\\)（并列规则除外）。概率很尖时，第 \\(k\\) 名可能已经是噪声；很平时，第 \\(k\\) 名仍可能丢掉合理同义。nucleus：支撑集大小自适应。Holtzman 等人的核是 <em>概率质量</em> 的最小头，不是 logit 间隙。\\(p=0.9\\) 表示丢掉最细的那截尾巴，头部多峰仍在。\\(p\\) 过小（0.5）会在很多上下文里接近贪心；\\(p=1\\) 等于不截。top-\\(k\\) 与 top-\\(p\\) 叠用时，若 \\(k\\) 很小，核没有空间，等于只用 \\(k\\)。调试「为什么多样性没了」先看 \\(k\\) 是否误设成 5。</p><p>实现细节：截断应在 softmax 之后按概率做，还是在 logits 上取最大再 mask，数值上应等价于在被拒位置置 \\(-\\infty\\)。与 JSON schema 一起时，先文法掩码再温度与核，否则核可能把唯一合法 token 当成尾巴切掉——合法集很小的时候 \\(p=0.9\\) 仍可能只剩非法头。正确的是：掩码后再定义核。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>温度对应 softmax 的尺度，与 SDPA 里除以 \\(\\sqrt{d_k}\\)、蒸馏里的 \\(T\\) 是同一类对象，但作用在词表维、且通常只在推理设置。它不改变训练过的相对排序（单调），改变的是采样熵。截断改变支撑集，是非单调的：某个 token 从「极小概率可被抽中」变成「概率精确为零」。开放生成的退化来自反复进入高概率短循环；核通过禁止最差的续写降低一次性崩盘，温度通过保留头部多峰降低永远同一句。两者修的病不同，所以常一起出现。</p><p>与束搜索的差别：核仍然 <em>随机</em>，下一步不是取集合内最大。\\(T\\to 0\\) 加任意截断都退回贪心，多样性为零。评测 pass@\\(N\\) 必须用随机采样；用贪心或极低 \\(T\\) 会严重低估覆盖。种子在张量并行下不可比特级复现，只能当弱可复现，不要用 seed 当正确性测试。</p><p><span class="marginnote">presence / frequency penalty 是另一组旋钮：按已出现 token 减 logit。它们与核正交，能减轻重复，也会伤害必须重复的标识符。调采样时一次动一组，否则无法归因。</span></p><h3 id="三者叠用时的支撑集" tabindex="-1">三者叠用时的支撑集 <a class="header-anchor" href="#三者叠用时的支撑集" aria-label="Permalink to &quot;三者叠用时的支撑集&quot;">​</a></h3><p>最终支撑集是文法掩码、top-\\(k\\)、top-\\(p\\) 的交。交为空时实现必须回退（放宽 \\(p\\)、忽略 \\(k\\)、或在合法集上贪心），否则卡死。回退策略属于协议，应写进引擎文档。并行工具调用或短枚举上，合法集可能只有两三个 token，此时 \\(T\\) 与 \\(p\\) 几乎无意义，应关截断。长散文上，关截断加高 \\(T\\) 会回到 Holtzman 批评的长尾。没有一组超参适合所有接口路径：聊天、JSON mode、工具参数应分配置，而不是全局一份 <code>temperature=0.7</code>。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>不要把温度当「创造性开关」交给最终用户无限拉高而不截断。不要在结构化输出路径上沿用闲聊的 \\(p\\)。不要用 top-\\(k=1\\) 冒充贪心同时还开着 \\(T=0.8\\)——\\(k=1\\) 已经决定唯一 token，\\(T\\) 无效。引擎默认值不同（有的默认 \\(p=1\\)，有的默认 \\(0.9\\)），兼容层必须显式下发，见 <a href="/llm/openai-compat-api">OpenAI 兼容协议</a>。</p><p>出处以 Holtzman et al. ICLR 2020 与 Fan et al. 的 top-\\(k\\) 故事生成为准。min-\\(p\\)、typical sampling 是后续变体，不在本篇展开。不要把某一聊天产品的默认温度写成科学常数。</p><p><span class="marginnote">训练与推理 \\(T\\) 不一致时，先修这个再谈「模型变傻」。RL 或蒸馏若在 \\(T=1\\) 的轨迹上学习，线上 \\(T=0\\) 会改变有效策略，指标移动不是权重损坏。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>温度改熵、不删 token；top-\\(k\\) 用固定集合截断；top-\\(p\\) 用概率质量自适应截断。</li><li>开放生成常用中等 \\(T\\) 加 \\(p\\approx 0.9\\)；代码与 JSON 用低 \\(T\\)，截断让给文法。</li><li>叠用时顺序与空集回退必须文档化；文法掩码应先于核。</li><li>\\(T=0\\) 或 \\(k=1\\) 即确定性路径，不要再假装在采样。</li><li>评测解码必须与产品一致；pass@\\(N\\) 与 RL 需要非贪心。</li><li>惩罚项、约束解码是正交层，分别调。</li><li>出处：Holtzman et al., <em>The Curious Case of Neural Text Degeneration</em>, ICLR 2020；Fan et al., hierarchical neural story generation（top-\\(k\\)）。</li></ul>',15))])}const x=l(k,[["render",d]]);export{E as __pageData,x as default};
